let IncActivos = toscalar(SecurityIncident | summarize arg_max(TimeGenerated, *) by IncidentNumber | where Status !~ 'Closed' | count);
let AlertasAltas = toscalar(SecurityAlert | where AlertSeverity in ('High','Medium') | count);
let Score = IncActivos * 3 + AlertasAltas;
print Riesgo = case(Score >= 50, 'Alto', Score >= 20, 'Medio', 'Bajo'), Score = Score, IncidentesActivos = IncActivos, AlertasHighMedium = AlertasAltas

let IncidentesActivos = toscalar(SecurityIncident | summarize arg_max(TimeGenerated, *) by IncidentNumber | where Status !~ 'Closed' | count);
let DeteccionesPersonalizadas = toscalar(SecurityAlert | where tostring(AlertName) has_any ('Custom', 'Personalizada', 'Deteccion personalizada') or tostring(ProviderName) has 'Custom' | count);
let AlertasMDO = toscalar(SecurityAlert | where ProductName has_any ('Office', 'Exchange', 'Defender for Office', 'MDO') | count);
let AlertasMDE = toscalar(SecurityAlert | where ProductName has_any ('Endpoint', 'MDE', 'Defender for Endpoint') | count);
let UsuariosRiesgoEntra = toscalar(AADUserRiskEvents | summarize dcount(UserPrincipalName));
let AlertasMDI = toscalar(SecurityAlert | where ProductName has_any ('Identity', 'MDI', 'Defender for Identity') | count);
let ConsentimientosOAuth = toscalar(CloudAppEvents | where ActionType has_any ('Consent', 'OAuth') | count);
union
(print KPI='Incidentes Activos', Valor=IncidentesActivos),
(print KPI='Detecciones Personalizadas', Valor=DeteccionesPersonalizadas),
(print KPI='Alertas Defender for Office', Valor=AlertasMDO),
(print KPI='Alertas Defender for Endpoint', Valor=AlertasMDE),
(print KPI='Usuarios en Riesgo Entra ID', Valor=UsuariosRiesgoEntra),
(print KPI='Alertas Defender for Identity', Valor=AlertasMDI),
(print KPI='Consentimientos OAuth (Cloud Apps)', Valor=ConsentimientosOAuth)

let StartToday = startofday(now());
let StartYesterday = startofday(ago(1d));
let EndYesterday = StartToday;
let IncHoy = toscalar(SecurityIncident | where TimeGenerated >= StartToday | summarize dcount(IncidentNumber));
let IncAyer = toscalar(SecurityIncident | where TimeGenerated between (StartYesterday .. EndYesterday) | summarize dcount(IncidentNumber));
let AltHoy = toscalar(SecurityAlert | where TimeGenerated >= StartToday | count);
let AltAyer = toscalar(SecurityAlert | where TimeGenerated between (StartYesterday .. EndYesterday) | count);
union
(print Indicador='Incidentes', Hoy=IncHoy, Ayer=IncAyer, Delta=IncHoy-IncAyer),
(print Indicador='Alertas', Hoy=AltHoy, Ayer=AltAyer, Delta=AltHoy-AltAyer)
